    k.fade.dead = false; k.fade.hasEmitter = true; k.fade.attached = false;
    KillBeamEffect(k);
    if (k.killBeamCounter != 5 || k.spawned != 1 || !k.fade.attached) { std::printf("007fb870_TEST FAIL\n"); return 1; }
