{
    if (s.gotSeat && s.campfireAlive) s.freedSeat = s.seatIndex;
    if (s.sitting || s.modeSit) {
        unsigned long delay = Random(delayRange);
        s.nextFrame = frame + delayBase + delay;
        ++s.standUps;
